import React, { useEffect, useState } from "react";
import axios from "axios";
import Navbar from "./Navbar";

import {
  Chart as ChartJS,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend
);

function Result() {
  const [labels, setLabels] = useState([]);
  const [votes, setVotes] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("token");

    axios
      .get("http://localhost:8080/api/result/1", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      .then((res) => {
        const names = res.data.map((r) => r.candidate);
        const counts = res.data.map((r) => r.votes);

        setLabels(names);
        setVotes(counts);
      });
  }, []);

  const data = {
    labels: labels,
    datasets: [
      {
        label: "Votes",
        data: votes,
        backgroundColor: [
          "#4CAF50",
          "#2196F3",
          "#FF9800",
          "#E91E63",
        ],
      },
    ],
  };

  return (
    <>
      <Navbar />

      <div className="container mt-4">
        <div className="card p-4">
          <h3 className="text-center mb-4">Election Results</h3>

          <Bar data={data} />
        </div>
      </div>
    </>
  );
}

export default Result;
